// Define the ScalarType enumeration
#[derive(Debug)]
enum ScalarType {
    Int32,
    Int64,
    Float32,
    Float64,
    Complex64,
    Complex128,
    Bytes,
    Object,
}

// Implement the function to convert ScalarType to its corresponding character code
fn sctype2char(sctype: ScalarType) -> &'static str {
    match sctype {
        ScalarType::Int32 => "l",
        ScalarType::Int64 => "q",
        ScalarType::Float32 => "f",
        ScalarType::Float64 => "d",
        ScalarType::Complex64 => "F",
        ScalarType::Complex128 => "D",
        ScalarType::Bytes => "S",
        ScalarType::Object => "O",
    }
}

fn main() {
    // Example usage
    let scalar = ScalarType::Float64;
    println!("The character code for Float64 is: {}", sctype2char(scalar));
}